(()=>{'use strict';let catalog=[];let selected='all';let search='';const names={salud:['Salud','Health'],profesional:['Profesional','Professional'],'real-estate':['Bienes raíces','Real estate'],negocios:['Negocios','Business'],finanzas:['Finanzas','Finance'],tecnologia:['Tecnología','Technology'],construccion:['Construcción','Construction'],marketing:['Marketing','Marketing'],idiomas:['Idiomas','Languages']};const categories=[['all','Todos','All'],...Object.entries(names).map(([k,v])=>[k,...v])];const icons={salud:'✚',profesional:'★','real-estate':'⌂',negocios:'▣',finanzas:'◈',tecnologia:'⌘',construccion:'⚒',marketing:'✦',idiomas:'◎'};const paArt={"construccion":"data:image/svg+xml;base64,","finanzas":"data:image/svg+xml;base64,","idiomas":"data:image/svg+xml;base64,","marketing":"data:image/svg+xml;base64,","negocios":"data:image/svg+xml;base64,","profesional":"data:image/svg+xml;base64,","real-estate":"data:image/svg+xml;base64,","salud":"data:image/svg+xml;base64,","tecnologia":"data:image/svg+xml;base64,"};const paPhotos={"profesional":"data:image/jpeg;base64,","tecnologia":"data:image/jpeg;base64,","construccion":"data:image/jpeg;base64,","negocios":"data:image/jpeg;base64,","marketing":"data:image/jpeg;base64,","idiomas":"data:image/jpeg;base64,","finanzas":"data:image/jpeg;base64,","real-estate":"data:image/jpeg;base64,","salud":"data:image/jpeg;base64,"};window.paFallbackArt=paArt;const lang=()=>window.plutonLanguage?.current()==='en'?'en':'es';const safe=s=>String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const b28CoursePhotos={"PA-101":"data:image/jpeg;base64,","RE-101":"data:image/jpeg;base64,","TE-101":"data:image/jpeg;base64,","MKT-201":"data:image/jpeg;base64,","FIN-201":"data:image/jpeg;base64,","ID-101":"data:image/jpeg;base64,","CO-101":"data:image/jpeg;base64,","PA-201":"data:image/jpeg;base64,","RE-102":"data:image/jpeg;base64,","PA-106":"data:image/jpeg;base64,","PA-105":"data:image/jpeg;base64,","HLT-201":"data:image/jpeg;base64,","PA-203":"data:image/jpeg;base64,","NE-101":"data:image/jpeg;base64,","AI-101":"data:image/jpeg;base64,","BUS-201":"data:image/jpeg;base64,","RE-201":"data:image/jpeg;base64,","MA-101":"data:image/jpeg;base64,","FI-101":"data:image/jpeg;base64,","PA-102":"data:image/jpeg;base64,"};function draw(){const root=document.getElementById('mainCatalog'),filters=document.getElementById('catalogFilters');if(!root||!filters)return;const en=lang()==='en';filters.innerHTML=categories.map(([id,es,enLabel])=>`<button type="button" class="${id===selected?'active':''}" data-catalog-filter="${id}">${safe(en?enLabel:es)}</button>`).join('');root.innerHTML=catalog.filter(c=>(selected==='all'||c.category===selected)&&(!search||[c.es,c.en,c.code,c.category].join(' ').toLocaleLowerCase().includes(search))).map(c=>`<article data-cat="${safe(c.category)}"><span class="code">${safe(c.code)}</span><div class="catalog-visual pa-illustrated" aria-hidden="true"><img src="${b28CoursePhotos[c.code]||paPhotos[c.category]||paPhotos.profesional}" onerror="console.warn('Course photo failed:',this.src);this.onerror=null;this.src=window.paFallbackArt?.[this.dataset.cat]||'assets/profesional.svg'" data-cat="${safe(c.category)}" alt="" loading="lazy" decoding="async" width="760" height="370"></div><h3>${safe(c[en?'en':'es'])}</h3><p>${safe((c.lessons||[]).length)} ${en?'introductory lessons':'lecciones introductorias'}</p><small>${safe((names[c.category]||[c.category,c.category])[en?1:0])}</small><a class="catalog-cta" href="courses.html?course=${encodeURIComponent(c.code)}">${en?'View lessons':'Ver lecciones'} →</a></article>`).join('');document.getElementById('catalogCount').textContent=(lang()==='en'?'Courses found: ':'Cursos encontrados: ')+catalog.filter(c=>(selected==='all'||c.category===selected)&&(!search||[c.es,c.en,c.code,c.category].join(' ').toLocaleLowerCase().includes(search))).length;filters.querySelectorAll('button').forEach(b=>b.addEventListener('click',()=>{selected=b.dataset.catalogFilter;draw()}))}document.addEventListener('DOMContentLoaded',()=>{document.getElementById('catalogSearch')?.addEventListener('input',e=>{search=e.target.value.trim().toLocaleLowerCase();draw()});fetch('catalog.json').then(r=>{if(!r.ok)throw Error('Catalog');return r.json()}).then(data=>{catalog=data;draw()}).catch(()=>{const el=document.getElementById('mainCatalog');if(el)el.textContent=lang()==='en'?'Catalog temporarily unavailable.':'Catálogo temporalmente no disponible.'});document.getElementById('languageToggle')?.addEventListener('click',()=>setTimeout(draw,0));});})();